input.content:
// Global variables
let stockData = [];
let selectedTicker = null;

// Color palette for sectors
const sectorColors = {
  'Information Technology': '#3b82f6',
  'Industry': '#f59e0b',
  'Energy': '#10b981',
  'Financial': '#8b5cf6',
  'ETF': '#6b7280'
};

// Format market cap to readable string
function formatMarketCap(value) {
  if (!value) return 'N/A';

  const trillion = 1e12;
  const billion = 1e9;
  const million = 1e6;

  if (value >= trillion) {
    return (value / trillion).toFixed(2) + 'T';
  } else if (value >= billion) {
    return (value / billion).toFixed(2) + 'B';
  } else if (value >= million) {
    return (value / million).toFixed(2) + 'M';
  }
  return value.toFixed(2);
}

// Initialize visualization
async function init() {
  try {
    // Load stock descriptions
    const data = await d3.csv('data/stock-descriptions.csv');

    // Process data
    stockData = data.map(d => ({
      ticker: d.ticker,
      name: d['full name'],
      sector: d.sector,
      marketCap: d.marketCap ? +d.marketCap : null,
      isETF: d.sector === 'ETF'
    }));

    // Create visualizations
    createBubbleChart();
    createTable();

  } catch (error) {
    console.error('Error loading data:', error);
  }
}

// Create bubble chart
function createBubbleChart() {
  const container = d3.select('#bubble-chart');
  const width = container.node().getBoundingClientRect().width;
  const height = 700;

  const svg = container
    .append('svg')
    .attr('width', width)
    .attr('height', height);

  // Calculate bubble sizes
  const marketCaps = stockData.filter(d => !d.isETF).map(d => d.marketCap);
  const minMarketCap = d3.min(marketCaps);
  const maxMarketCap = d3.max(marketCaps);

  // Radius scale for market cap
  const radiusScale = d3.scaleSqrt()
    .domain([minMarketCap, maxMarketCap])
    .range([15, 50]);

  // ETF uniform size
  const etfRadius = 20;

  // Add radius to data
  stockData.forEach(d => {
    d.radius = d.isETF ? etfRadius : radiusScale(d.marketCap);
  });

  // Get unique sectors
  const sectors = [...new Set(stockData.map(d => d.sector))];

  // Calculate sector positions using circle packing layout
  const sectorPositions = {};
  const padding = 100;
  const cols = 3;
  const rows = Math.ceil(sectors.length / cols);
  const cellWidth = (width - padding * 2) / cols;
  const cellHeight = (height - padding * 2) / rows;

  sectors.forEach((sector, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    sectorPositions[sector] = {
      x: padding + col * cellWidth + cellWidth / 2,
      y: padding + row * cellHeight + cellHeight / 2
    };
  });

  // Create force simulation
  const simulation = d3.forceSimulation(stockData)
    .force('charge', d3.forceManyBody().strength(5))
    .force('x', d3.forceX(d => sectorPositions[d.sector].x).strength(0.3))
    .force('y', d3.forceY(d => sectorPositions[d.sector].y).strength(0.3))
    .force('collision', d3.forceCollide().radius(d => d.radius + 2))
    .force('center', d3.forceCenter(width / 2, height / 2).strength(0.05));

  // Create tooltip
  const tooltip = d3.select('body')
    .append('div')
    .attr('class', 'tooltip');

  // Create bubble groups
  const bubbleGroups = svg.selectAll('.bubble-group')
    .data(stockData)
    .join('g')
    .attr('class', 'bubble-group');

  // Add circles
  const bubbles = bubbleGroups
    .append('circle')
    .attr('class', 'bubble')
    .attr('r', d => d.radius)
    .attr('fill', d => sectorColors[d.sector])
    .attr('opacity', 0.85)
    .on('mouseover', function(event, d) {
      if (!d.isETF) {
        tooltip
          .html(`
            <div class="tooltip-ticker">${d.ticker}</div>
            <div class="tooltip-name">${d.name}</div>
            <div class="tooltip-sector">${d.sector}</div>
          `)
          .style('left', (event.pageX + 15) + 'px')
          .style('top', (event.pageY - 15) + 'px')
          .classed('visible', true);
      }
    })
    .on('mouseout', function() {
      tooltip.classed('visible', false);
    })
    .on('click', function(event, d) {
      selectStock(d.ticker);
    });

  // Add labels
  const labels = bubbleGroups
    .append('text')
    .attr('class', 'bubble-label')
    .text(d => d.ticker)
    .style('font-size', d => Math.min(d.radius / 2.5, 14) + 'px');

  // Update positions on simulation tick
  simulation.on('tick', () => {
    bubbleGroups.attr('transform', d => `translate(${d.x},${d.y})`);
  });

  // Create legend
  createLegend(sectors);

  // Store references for later use
  window.bubbles = bubbles;
  window.simulation = simulation;
}

// Create legend
function createLegend(sectors) {
  const legend = d3.select('.chart-section')
    .append('div')
    .attr('class', 'legend');

  legend.append('div')
    .attr('class', 'legend-title')
    .text('Sectors');

  const items = legend.append('div')
    .attr('class', 'legend-items');

  items.selectAll('.legend-item')
    .data(sectors)
    .join('div')
    .attr('class', 'legend-item')
    .html(d => `
      <div class="legend-color" style="background-color: ${sectorColors[d]}"></div>
      <span>${d}</span>
    `);
}

// Create data table
function createTable() {
  const tableSection = d3.select('.table-section');

  const tableContainer = tableSection.append('div')
    .attr('class', 'table-container');

  const table = tableContainer.append('table');

  // Create header
  const thead = table.append('thead');
  thead.append('tr')
    .selectAll('th')
    .data(['Ticker', 'Company Name', 'Sector', 'Market Cap'])
    .join('th')
    .text(d => d);

  // Create body
  const tbody = table.append('tbody');

  const rows = tbody.selectAll('tr')
    .data(stockData)
    .join('tr')
    .on('click', function(event, d) {
      selectStock(d.ticker);
    });

  // Add cells
  rows.each(function(d) {
    const row = d3.select(this);

    row.append('td')
      .attr('class', 'ticker-cell')
      .text(d.ticker);

    row.append('td')
      .text(d.name);

    row.append('td')
      .text(d.sector);

    row.append('td')
      .attr('class', 'market-cap-cell')
      .text(formatMarketCap(d.marketCap));
  });

  // Store reference for later use
  window.tableRows = rows;
}

// Select stock (called when clicking bubble or table row)
function selectStock(ticker) {
  selectedTicker = ticker;

  // Update bubble selection
  window.bubbles
    .classed('selected', d => d.ticker === ticker)
    .attr('opacity', d => d.ticker === ticker ? 1 : 0.85);

  // Update table selection
  window.tableRows
    .classed('selected', d => d.ticker === ticker);

  // Scroll selected row into view
  const selectedRow = window.tableRows.filter(d => d.ticker === ticker).node();
  if (selectedRow) {
    selectedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', init);

